            // Act
            Choice_Template choiceTemplate = _choice.Render(_ticket, _ticketHelper, null, Arg.Any<bool>());
            var actual = choiceTemplate.Handicap.handicap;

            // Assert            
            Assert.IsNullOrEmpty(actual);
